  3055  /* kex_method_strlen
  3056   * Calculate the length of a particular method list's resulting string
  3057   * Includes SUM(strlen() of each individual method plus 1 (for coma)) - 1
  3058   * (because the last coma isn't used)
  3059   * Another sign of bad coding practices gone mad.  Pretend you don't see this.
  3060   */
  3061  static size_t
  3062  kex_method_strlen(LIBSSH2_COMMON_METHOD ** method)
  3063  {
  3064      size_t len = 0;
  3065
  3066      if(!method || !*method) {
  3067          return 0;
  3068      }
  3069
  3070      while(*method && (*method)->name) {
  3071          len += strlen((*method)->name) + 1;
  3072          method++;
  3073      }
  3074
  3075      return len - 1;
  3076  }
